import 'server-only'

/** Send a page-view event to the configured analytics service. */
export async function logPageView(path: string): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT
  if (!endpoint) {
    throw new Error('ANALYTICS_ENDPOINT is not configured')
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(process.env.ANALYTICS_API_KEY
        ? { Authorization: `Bearer ${process.env.ANALYTICS_API_KEY}` }
        : {}),
    },
    body: JSON.stringify({ event: 'page_view', path, timestamp: new Date().toISOString() }),
  })

  if (!response.ok) {
    throw new Error(`Analytics request failed with status ${response.status}`)
  }
}

